/* Patch-loader for the Reflecta DigitDia Evolution (NT96660, firmware 2.0).
 *
 * Runs as FWFS601T.BIN (the loader runs it from RAM; flash is never written). It contains no Reflecta code:
 *   1. read the scanner's own compressed firmware from flash (block 8 = 0x8000) with the loader's read routine
 *   2. decompress it to 0x80000000 with the loader's decompressor
 *   3. fingerprint it (size + 32-bit word sum of the whole image). Only an exact stock FW 2.0 image is patched;
 *      anything else boots unpatched
 *   4. apply our patch words (patches.h, generated by make_pldr.py; includes the fixed header checksum)
 *   5. restore the loader's handoff block with the boot flags of a normal flash boot (4 card -> 8 flash)
 *   6. flush the caches and jump to the firmware entry, exactly like the loader does
 * 0. before calling any bootloader routine, check that the routines are exactly the ones this was made for:
 *    a 32-bit FNV-1a hash of each routine's code (sig.h, generated from a flash dump; no bootloader code is
 *    included). On a mismatch it stops (the scanner doesn't start; remove the card -> stock).
 * Loader routines used (resident in RAM, addresses from loader analysis 2026-11-15):
 *   0x8ff0d984 storage init, 0x8ff0d408 storage READ (never the erase/program routine 0x8ff0cc88),
 *   0x8ff0ca88 storage deinit, 0x8ff0815c BCL LZ decompress, 0x8ff08110 D-cache flush, 0x8ff080b4 I-cache invalidate.
 */
typedef unsigned int u32;
typedef unsigned char u8;
#include "patches.h"
#include "sig.h"

#define FW        ((volatile u32 *)0x80000000)
#define BUF       ((u8 *)0x8c000000)           /* compressed firmware read buffer (stock: 3.4 MB) */
#define HANDOFF   ((volatile u32 *)0x8e000080) /* our own copy of the handoff block the loader wrote */
#define FW_BLOCK  8                            /* 4 KB units: flash 0x8000 */

#define st_init   ((int (*)(void))0x8ff0d984)
#define st_read   ((int (*)(u32 blk, u32 len, void *dst, u32 mode))0x8ff0d408)
#define st_deinit ((void (*)(void))0x8ff0ca88)
#define unlz      ((void (*)(const void *src, void *dst, u32 len))0x8ff0815c)
#define dflush    ((void (*)(void))0x8ff08110)
#define iinval    ((void (*)(void))0x8ff080b4)

static u32 be32(const u8 *p)
{
    return ((u32)p[0] << 24) | ((u32)p[1] << 16) | ((u32)p[2] << 8) | p[3];
}

static void halt(void)
{
    for (;;)
        ;
}

static u32 fnv(const volatile u32 *p, u32 nwords)
{
    u32 h = 0x811c9dc5u;
    while (nwords--)
        h = (h ^ *p++) * 16777619u;
    return h;
}

void pldr_main(void)
{
    u32 usz, csz, sum, i, ok;

    for (i = 0; i < NSIG; i++)
        if (fnv((const volatile u32 *)sig_addr[i], sig_len[i] >> 2) != sig_hash[i])
            halt();
    if (st_init() < 0)
        halt();
    if (st_read(FW_BLOCK, 0x1000, BUF, 2) < 0)
        halt();
    if (be32(BUF) != 0x42434c31)               /* "BCL1" */
        halt();
    usz = be32(BUF + 8);
    csz = be32(BUF + 12);
    if (usz < 0x1000 || usz > 0x0a000000 || csz > 0x00800000)
        halt();
    if (st_read(FW_BLOCK, csz + 16, BUF, 2) < 0)
        halt();
    st_deinit();
    unlz(BUF + 16, (void *)FW, csz);

    /* fingerprint: exact stock image? */
    sum = 0;
    for (i = 0; i < (usz >> 2); i++)
        sum += FW[i];
    ok = (usz == STOCK_SIZE) && (FW[0x68 >> 2] == STOCK_SIZE) && (sum == STOCK_SUM);
    if (ok)
        for (i = 0; i < NPATCH; i++)
            FW[patch_off[i] >> 2] = patch_val[i];

    /* handoff block 0x80..0xab, as the loader wrote it for us, but as a normal flash boot */
    for (i = 0; i < 11; i++)
        FW[0x20 + i] = HANDOFF[i];
    FW[0x94 >> 2] = (HANDOFF[(0x94 - 0x80) >> 2] & ~4u) | 8u;
    FW[0x98 >> 2] = FW[0x68 >> 2];

    dflush();
    iinval();
    ((void (*)(void))FW[0])();
    halt();
}
